// ──────────────────────────────────────────────────────────────────────────
// dispatch-engine  —  Post-order vendor selection (Supabase Edge Function)
// ──────────────────────────────────────────────────────────────────────────
// Invoked by:
//   • `pg_net.http_post` from the AFTER-INSERT trigger on `orders` (when a
//     new order has just been created with status='pending' and vendor_id
//     now needs assignment), and
//   • `pg_cron` once a minute via the `cron.schedule` job
//     `dispatch-stuck-orders` (catches any order whose
//     `dispatch_attempt` has stalled — vendor didn't accept in time).
//
// Request body: { order_id: string|null, attempt?: number }
//   - When order_id is null we scan for any pending order with
//     `vendor_id IS NULL AND created_at < now() - interval '30 seconds'`
//     and dispatch each one.
//   - When attempt is provided it overrides the dispatched attempt counter;
//     useful for the pg_cron retry path.
//
// Atomicity: the function performs all DB writes via guarded REST calls
// anchored by `WHERE status='pending' AND vendor_id IS NULL` so concurrent
// invocations don't double-assign.
//
// Selection algorithm (mirrors `services/dispatchService.ts` +
// `services/vendorService.ts` exactly):
//   1. Load order row; reject if status != 'pending' (already moved on).
//   2. Load `order_rejections (vendor_id)` set for this order.
//   3. Fetch candidate vendors: is_active AND is_verified AND
//      (small_stock > 0 OR large_stock > 0 per requested size) AND
//      delivery_radius_km >= haversine distance from order's delivery_lat/lng.
//   4. Sort per dispatch algorithm (premium first; if order.is_urgent sort
//      by `avg_delivery_mins*-0.5 + rating*8` desc; else the blended score
//      0.6*distance/worst_dist + 0.25*(1-rating/5) + 0.15*priceScore).
//   5. Lock the SELECTed candidate's vendor row via an UPDATE
//      `WHERE status='pending' AND vendor_id IS NULL` (single-Vendor RPC
//      assignment). If the rowcount is zero, that means another function
//      invocation beat us — log and exit.
//   6. If no candidate is available, AND `attempt >= max_dispatch_retries`,
//      cancel the order with a reason; else log and let the next attempt
//      retry.
//   7. As Edge Functions can't reliably `setTimeout` beyond the runtime
//      timeout, we do NOT schedule the next-attempt timer here. Instead the
//      `pg_cron` poller (every minute) catches the order if the vendor
//      hasn't accepted in time — the order's accepted_at trigger our
//      `send-notification` call.
//
// Authorisation:
//   • Trigger path (pg_net.http_post): no Authorization header. The only
//     way to invoke this function is from inside the database (postgres
//     role). Function reads/writes operate as the service_role through
//     SUPABASE_SERVICE_ROLE_KEY (a platform-injected env var).
//   • REST path: requires `Authorization: Bearer <service_role-key>` or
//     `apikey: <service_role-key>` header.
// ──────────────────────────────────────────────────────────────────────────

import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { handleCors, jsonResponse, CORS_HEADERS } from '../_shared/cors.ts';

const SUPABASE_URL    = Deno.env.get('SUPABASE_URL') ?? '';
const SERVICE_ROLE    = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';
const DISPATCH_TIMEOUT_MS = 30 * 1000;          // 30s default wake interval
const MAX_RETRIES_DEFAULT = 5;

interface Order {
  id: string;
  customer_id: string;
  vendor_id: string | null;
  size: 'small' | 'large';
  quantity: number;
  is_urgent: boolean;
  delivery_lat: number;
  delivery_lng: number;
  status: string;
  dispatch_attempt: number;
}

interface VendorRow {
  id: string;
  user_id: string;
  business_name: string;
  lat: number;
  lng: number;
  small_stock: number;
  large_stock: number;
  small_price: number;
  large_price: number;
  rating: number;
  delivery_radius_km: number;
  avg_delivery_mins: number;
  is_premium: boolean;
}

interface RejectionRow { vendor_id: string; }

// ─────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────

/** Haversine great-circle distance (km). */
function haversineKm(
  lat1: number, lng1: number, lat2: number, lng2: number,
): number {
  const R = 6371;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLng = ((lng2 - lng1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

/** Blended-vendorService score (smaller = better). Mirrors vendorService.ts */
function vendorServiceScore(
  v: VendorRow,
  size: 'small' | 'large',
  worstDist: number,
  worstPrice: number,
  bestPrice: number,
): number {
  const dist = haversineKm(v.lat, v.lng, 0, 0);                                                          // placeholder, computed in caller
  const priceFor = size === 'small' ? v.small_price : v.large_price;
  const priceScore = worstPrice > bestPrice
    ? (priceFor - bestPrice) / (worstPrice - bestPrice)
    : 0;
  const distScore   = dist / worstDist;
  const ratingScore = 1 - (v.rating || 0) / 5;
  return 0.6 * distScore + 0.25 * ratingScore + 0.15 * priceScore;
}

/** Urgent sort key (smaller = better). Mirrors dispatchService.ts urgent weighting. */
function urgentRank(v: VendorRow): number {
  return ((v.avg_delivery_mins || 30) * -0.5) + ((v.rating || 0) * 8);
}

/** Authorised REST call helper. */
async function rpc<T = any>(path: string, init: RequestInit = {}): Promise<T> {
  if (!SUPABASE_URL || !SERVICE_ROLE) {
    throw new Error('Server misconfigured: SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY missing');
  }
  const res = await fetch(`${SUPABASE_URL}${path}`, {
    ...init,
    headers: {
      'Content-Type': 'application/json',
      'apikey': SERVICE_ROLE,
      'Authorization': `Bearer ${SERVICE_ROLE}`,
      ...(init.headers ?? {}),
    },
  });
  if (!res.ok) {
    const t = await res.text();
    throw new Error(`Supabase REST ${res.status}: ${t}`);
  }
  return await res.json() as T;
}

/** PG REST query with apikey + bearer preflight. */
async function selectTable<T = any>(table: string, params: Record<string, string>): Promise<T[]> {
  const qs = new URLSearchParams(params).toString();
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}?${qs}`, {
    headers: {
      'apikey': SERVICE_ROLE,
      'Authorization': `Bearer ${SERVICE_ROLE}`,
      'Accept': 'application/json',
      'Prefer': 'return=representation',
    },
  });
  if (!res.ok) {
    const t = await res.text();
    throw new Error(`select ${table} ${res.status}: ${t}`);
  }
  return await res.json() as T[];
}

/** Atomic guard: UPDATE the order row only if still pending. */
async function assignVendor(
  orderId: string,
  vendorId: string,
  newAttempt: number,
): Promise<number> {
  // PATCH entries as `...?id=eq.<uuid>` are atomic.
  const res = await fetch(
    `${SUPABASE_URL}/rest/v1/orders?id=eq.${encodeURIComponent(orderId)}&status=eq.pending&vendor_id=is.null`,
    {
      method: 'PATCH',
      headers: {
        'apikey': SERVICE_ROLE,
        'Authorization': `Bearer ${SERVICE_ROLE}`,
        'Content-Type': 'application/json',
        'Prefer': 'return=representation,count',
      },
      body: JSON.stringify({
        vendor_id: vendorId,
        dispatch_attempt: newAttempt,
      }),
    },
  );
  const text = await res.text();
  if (!res.ok) {
    throw new Error(`assignVendor ${res.status}: ${text}`);
  }
  return parseInt(res.headers.get('Content-Range')?.split('/')[1] ?? '0', 10);
}

/** Cancel an order due to no eligible vendor or retries exhausted. */
async function cancelOrder(orderId: string, reason: string): Promise<number> {
  const res = await fetch(
    `${SUPABASE_URL}/rest/v1/orders?id=eq.${encodeURIComponent(orderId)}&status=eq.pending`,
    {
      method: 'PATCH',
      headers: {
        'apikey': SERVICE_ROLE,
        'Authorization': `Bearer ${SERVICE_ROLE}`,
        'Content-Type': 'application/json',
        'Prefer': 'return=representation,count',
      },
      body: JSON.stringify({
        status: 'cancelled',
        cancellation_reason: reason,
        cancelled_at: new Date().toISOString(),
      }),
    },
  );
  await res.text();
  return parseInt(res.headers.get('Content-Range')?.split('/')[1] ?? '0', 10);
}

// ─────────────────────────────────────────────────────────────────────────
// Dispatch core
// ─────────────────────────────────────────────────────────────────────────

async function dispatchOrder(order: Order): Promise<{ vendor_id: string | null; reason?: string }> {
  // Load rejections for this order.
  const rejections: RejectionRow[] = await selectTable<RejectionRow>(
    'order_rejections',
    {
      select: 'vendor_id',
      'order_id': `eq.${order.id}`,
    },
  );
  const rejectedIds = new Set(rejections.map((r) => r.vendor_id));

  // Load candidate vendors.
  const sizeCol = order.size === 'small' ? 'small_stock' : 'large_stock';
  const candidates: VendorRow[] = await selectTable<VendorRow>(
    'vendors',
    {
      select: 'id,user_id,business_name,lat,lng,small_stock,large_stock,small_price,large_price,rating,delivery_radius_km,avg_delivery_mins,is_premium',
      is_active: 'eq.true',
      is_verified: 'eq.true',
      [sizeCol]: 'gt.0',
    },
  );

  // Filter inside radius and not previously rejected.
  const viable = candidates.filter((v) => {
    if (rejectedIds.has(v.id)) return false;
    const dist = haversineKm(order.delivery_lat, order.delivery_lng, v.lat, v.lng);
    const radius = v.delivery_radius_km;
    return radius == null || dist <= radius;
  });

  // Note: do NOT early-return on viable.length === 0 here. The bump further
  // down needs to run unconditionally so dispatch_attempt advances and the
  // cron poller's cancellation guard eventually fires.

  // Sort
  if (order.is_urgent) {
    viable.sort((a, b) => urgentRank(a) - urgentRank(b));   // ascending = best urgency first
  } else {
    const prices = viable.map((v) =>
      order.size === 'small' ? (v.small_price || 0) : (v.large_price || 0),
    );
    const worstPrice = Math.max(...prices, 1);
    const bestPrice  = Math.min(...prices) || 0;
    const worstDist  = Math.max(...viable.map((v) =>
      haversineKm(order.delivery_lat, order.delivery_lng, v.lat, v.lng)), 1);

    // Premium vendors first; inside premium tier (and non-premium tier),
    // sort by blended score.
    viable.sort((a, b) => {
      if (a.is_premium && !b.is_premium) return -1;
      if (!a.is_premium && b.is_premium) return 1;
      const sa = vendorServiceScore(a, order.size, worstDist, worstPrice, bestPrice);
      const sb = vendorServiceScore(b, order.size, worstDist, worstPrice, bestPrice);
      return sa - sb;
    });
  }

  // Try assigning each candidate in order; only one UPDATE will succeed
  // because of the `WHERE status='pending' AND vendor_id IS NULL` guard.
  const newAttempt = order.dispatch_attempt + 1;
  let attemptedAssign = false;
  for (const v of viable) {
    try {
      const updated = await assignVendor(order.id, v.id, newAttempt);
      if (updated > 0) {
        return { vendor_id: v.id };
      }
      attemptedAssign = true;
    } catch {
      // Try next candidate — a transient request failure shouldn't kill the
      // whole dispatch loop.
    }
  }
  // Critical: even when no candidate was viable (or all assignments lost
  // the race), bump `dispatch_attempt` so the cron poller's
  // `dispatch_attempt + 1 >= max_retries` cancellation guard eventually
  // fires. Without this, an order with no candidates stays at
  // dispatch_attempt=0 forever and is never cancelled.
  if (!attemptedAssign || viable.length === 0) {
    try {
      await fetch(
        `${SUPABASE_URL}/rest/v1/orders?id=eq.${encodeURIComponent(order.id)}&status=eq.pending&vendor_id=is.null`,
        {
          method: 'PATCH',
          headers: {
            'apikey': SERVICE_ROLE,
            'Authorization': `Bearer ${SERVICE_ROLE}`,
            'Content-Type': 'application/json',
            'Prefer': 'return=minimal',
          },
          body: JSON.stringify({ dispatch_attempt: newAttempt }),
        },
      );
    } catch {
      // Non-fatal — the cron poller will retry on the next tick.
    }
  }
  return {
    vendor_id: null,
    reason: viable.length === 0 ? 'no_vendors_available' : 'all_assignments_lost_race',
  };
}

async function fetchPendingOrders(): Promise<Order[]> {
  // Outdated pending orders that have no vendor assigned. The 30s window
  // ensures we don't immediately re-dispatch an order whose trigger
  // invocation is still in flight.
  return await selectTable<Order>('orders', {
    select: 'id,customer_id,vendor_id,size,quantity,is_urgent,delivery_lat,delivery_lng,status,dispatch_attempt',
    status: 'eq.pending',
    vendor_id: 'is.null',
    created_at: 'lt.' +
      new Date(Date.now() - 30 * 1000).toISOString(),
    order: 'created_at.asc',
    limit: '20',
  });
}

async function loadOrder(orderId: string): Promise<Order | null> {
  const rows = await selectTable<Order>('orders', {
    select: 'id,customer_id,vendor_id,size,quantity,is_urgent,delivery_lat,delivery_lng,status,dispatch_attempt',
    id: `eq.${orderId}`,
    limit: '1',
  });
  return rows[0] ?? null;
}

async function loadMaxRetries(): Promise<number> {
  const rows = await selectTable<{ value: string }>('system_settings', {
    select: 'value',
    key: 'eq.max_dispatch_retries',
    limit: '1',
  });
  return parseInt(rows[0]?.value ?? String(MAX_RETRIES_DEFAULT), 10);
}

// ─────────────────────────────────────────────────────────────────────────
// Entry
// ─────────────────────────────────────────────────────────────────────────

Deno.serve(async (req: Request) => {
  const cors = handleCors(req);
  if (cors) return cors;

  // Pre-flight aside — the pg_net path doesn't send Authorization.
  // We don't enforce JWT membership here; only the postgres role can
  // call pg_net, and admin/REST callers authenticate via service_role_key
  // which we require for all DB writes. No JWT secret verification needed
  // for the trigger path.
  const isRestCall = req.method === 'POST';

  let body: { order_id?: string | null; attempt?: number } = {};
  if (isRestCall) {
    try { body = await req.json(); }
    catch { return jsonResponse({ error: 'invalid_json' }, { status: 400 }); }
  }

  const maxRetries = await loadMaxRetries().catch(() => MAX_RETRIES_DEFAULT);

  // Either dispatch one order or scan for stuck orders.
  const targetOrders: Order[] = [];
  if (body && body.order_id) {
    const o = await loadOrder(body.order_id);
    if (o && o.status === 'pending' && o.vendor_id === null) {
      targetOrders.push(o);
    }
  } else {
    const stuck = await fetchPendingOrders();
    targetOrders.push(...stuck);
  }

  const results: { order_id: string; vendor_id: string | null; reason?: string }[] = [];
  for (const o of targetOrders) {
    let cancelledFlag = false;
    let reason: string | undefined;
    try {
      const r = await dispatchOrder(o);
      results.push({ order_id: o.id, vendor_id: r.vendor_id, reason: r.reason });
      if (!r.vendor_id && o.dispatch_attempt + 1 >= maxRetries) {
        const reasonText =
          r.reason === 'no_vendors_available'
            ? 'لا يوجد بائع متاح في منطقتك حاليًا. حاول مجددًا لاحقًا'
            : 'لم يتمكن أي بائع من قبول طلبك. حاول مرة أخرى';
        await cancelOrder(o.id, reasonText);
        cancelledFlag = true;
      }
    } catch (e) {
      reason = (e as Error)?.message ?? 'dispatch_error';
      results.push({ order_id: o.id, vendor_id: null, reason });
    }
    // Even cancellation can be reported for cron observability.
    if (cancelledFlag) {
      // Emit log line for log surface; future joins onto the function log.
      console.log(JSON.stringify({ evt: 'order_cancelled', order_id: o.id, ts: new Date().toISOString() }));
    }
  }

  return jsonResponse({
    processed: results.length,
    results,
    max_retries: maxRetries,
  });
});

// ──────────────────────────────────────────────────────────────────────────
// _shared/cors.ts  —  Shared CORS helper for all Ambobtak Edge Functions
// ──────────────────────────────────────────────────────────────────────────
// Why: pg_net.http_post invokes these functions server-to-server with no
// browser involved, so CORS is technically irrelevant for the trigger path.
// But an admin path or future dashboard may POST via fetch from a browser,
// so we pre-flight anyway and reuse a single header set.
//
// Convention: each Edge function's main `Deno.serve` calls `handleCors(req)`
// first. If it returned a Response, that's the preflight reply — return it
// as-is. Otherwise the function continues with the actual request.
// ──────────────────────────────────────────────────────────────────────────

export const CORS_HEADERS: Record<string, string> = {
  'Access-Control-Allow-Origin':   '*',
  'Access-Control-Allow-Methods':  'POST, OPTIONS, GET',
  'Access-Control-Allow-Headers':  'authorization, x-client-info, apikey, content-type, x-idempotency-key',
  'Access-Control-Max-Age':        '86400',
};

/** If the request is a CORS preflight (OPTIONS), return the 204 outlet. */
export function handleCors(req: Request): Response | null {
  if (req.method === 'OPTIONS') {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }
  return null;
}

/** Wrap a JSON body with CORS headers (used for normal HTTP responses). */
export function jsonResponse(body: unknown, init: ResponseInit = {}): Response {
  return new Response(JSON.stringify(body), {
    ...init,
    headers: {
      'Content-Type': 'application/json',
      ...CORS_HEADERS,
      ...(init.headers ?? {}),
    },
  });
}
